-- Demo data for GiselX: one distributor company, one login, item mappings and both upload templates.
-- Generated by scratchpad/demogen. Re-runnable: it aborts if the demo company already exists.
SET QUOTED_IDENTIFIER ON;
SET ANSI_NULLS ON;
SET XACT_ABORT ON;
SET NOCOUNT ON;
BEGIN TRANSACTION;

IF EXISTS (SELECT 1 FROM dbo.Company WHERE Name = N'Demo Distributor Nusantara')
BEGIN
    ROLLBACK TRANSACTION;
    RAISERROR(N'Demo data already present. Run the cleanup script first.', 16, 1);
    RETURN;
END

DECLARE @CompanyId int;
DECLARE @Now datetime2 = SYSUTCDATETIME();

VALUES (N'Demo Distributor Nusantara', N'Jl. Demo Raya No. 1, Jakarta', N'demo.distributor@example.com', 5, 3, 1);
SET @CompanyId = SCOPE_IDENTITY();

-- Distributor login
     SecurityStamp, ConcurrencyStamp, PhoneNumberConfirmed, TwoFactorEnabled, LockoutEnabled,
     AccessFailedCount, FirstName, LastName, CompanyId)
VALUES (N'74b67fec-6dc7-4092-9a68-62f5c699cfcd', N'demo.dist', N'DEMO.DIST', N'demo.dist@example.com', N'DEMO.DIST@EXAMPLE.COM', 1, N'AQAAAAIAAYagAAAAEFIsosZ7JUTu7KH/8C/EKxjjX36ieFaAi6ITEspQXTwD5wOoM0KBbC+7tYFIJgfARA==',
        N'7F49BC02BA4E4A5F99F1D47AD74E8297', N'ae90ca0b-bc15-4942-889e-f322ea17043d', 0, 0, 1, 0, N'Demo', N'Distributor', @CompanyId);

SELECT N'74b67fec-6dc7-4092-9a68-62f5c699cfcd', Id FROM [identity].AspNetRoles WHERE Name = N'Distributor';

-- Item mappings: DMO-001..DMO-004 active, DMO-005 deliberately inactive.

-- Stock upload template matching demo-stock-2026-09-04.xlsx
DECLARE @StockTemplateId int;
VALUES (@CompanyId, N'Demo Stock Template', N'Stock', 1, 2, N'KODE BARANG' + NCHAR(31) + N'NAMA BARANG' + NCHAR(31) + N'KEMASAN' + NCHAR(31) + N'ISI PER KARTON' + NCHAR(31) + N'NETTO' + NCHAR(31) + N'SATUAN' + NCHAR(31) + N'SALDO AWAL' + NCHAR(31) + N'MASUK PO' + NCHAR(31) + N'SALDO AKHIR' + NCHAR(31) + N'NO BATCH' + NCHAR(31) + N'TANGGAL EXPIRED' + NCHAR(31) + N'HARGA SATUAN', 1, @Now, N'demo-seed');
SET @StockTemplateId = SCOPE_IDENTITY();


-- Sellout upload template matching demo-sellout-2026-08-31.xlsx
DECLARE @SelloutTemplateId int;
VALUES (@CompanyId, N'Demo Sellout Template', N'Sellout', 1, 2, N'KODE PELANGGAN' + NCHAR(31) + N'NAMA PELANGGAN' + NCHAR(31) + N'ALAMAT' + NCHAR(31) + N'KODE BARANG' + NCHAR(31) + N'NAMA BARANG' + NCHAR(31) + N'KEMASAN' + NCHAR(31) + N'NO FAKTUR' + NCHAR(31) + N'TANGGAL FAKTUR' + NCHAR(31) + N'QTY' + NCHAR(31) + N'SATUAN' + NCHAR(31) + N'HARGA SATUAN' + NCHAR(31) + N'NILAI KOTOR' + NCHAR(31) + N'DISKON' + NCHAR(31) + N'NILAI BERSIH', 1, @Now, N'demo-seed');
SET @SelloutTemplateId = SCOPE_IDENTITY();


COMMIT TRANSACTION;
PRINT N'Demo data created.';
SELECT Id AS DemoCompanyId, Name FROM dbo.Company WHERE Name = N'Demo Distributor Nusantara';
